// Publications hero: a VNA screen. Left: Smith chart with a resonant impedance
// loop swept across 4–8 GHz (glowing head + persistence tail). Right: |S11| in dB
// with a sweeping marker and the −10 dB line. Readouts stay in sync.
import { canvasScene } from "./core/canvas.js";
import { motionAllowed } from "./core/manager.js";
import { profile } from "../data/profile.js";

let instance;
const STEPS = 400;

// Γ(u): a loop that passes close to the matched centre near 5.8 GHz
const gamma = (u) => {
  const th = -0.263 + u * Math.PI * 2 * 1.08;
  const cx = 0.42 * Math.cos(-0.35),
    cy = 0.42 * Math.sin(-0.35);
  const rho = 0.44 - 0.02 * u;
  return [cx + rho * Math.cos(th), cy + rho * Math.sin(th)];
};
const locus = Array.from({ length: STEPS + 1 }, (_, i) => gamma(i / STEPS));
const dbAt = (i) =>
  Math.max(-38, 20 * Math.log10(Math.max(1e-3, Math.hypot(...locus[i]))));

export function init(container, options = {}) {
  destroy();
  const freq = container.parentElement.querySelector("[data-frequency]"),
    s11 = container.parentElement.querySelector("[data-s11]");
  let intro = 0;
  instance = canvasScene(
    container,
    ({ ctx, w, h, t, dt, still, colors: c }) => {
      intro = still ? 1 : Math.min(1, intro + dt * 0.9);
      const stacked = w < 520;
      const R = stacked
        ? Math.min(w * 0.36, h * 0.3)
        : Math.min(w * 0.27, h * 0.43);
      const sx = stacked ? w / 2 : R + 22,
        sy = stacked ? R + 14 : h / 2;
      const map = ([gr, gi]) => [sx + gr * R, sy - gi * R];
      const glowLine = (pts, color, width, blur, alpha = 1) => {
        ctx.save();
        ctx.globalAlpha = alpha;
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.shadowColor = color;
        ctx.shadowBlur = blur;
        ctx.beginPath();
        pts.forEach((p, i) => (i ? ctx.lineTo(...p) : ctx.moveTo(...p)));
        ctx.stroke();
        ctx.restore();
      };

      // --- Smith grid (drawn in over the intro) ---
      ctx.save();
      ctx.globalAlpha = 0.55 * intro;
      ctx.strokeStyle = c.phosphor;
      ctx.lineWidth = 0.6;
      ctx.beginPath();
      ctx.arc(sx, sy, R, 0, Math.PI * 2);
      ctx.moveTo(sx - R, sy);
      ctx.lineTo(sx + R, sy);
      for (const r of [0.2, 0.5, 1, 2, 5]) {
        ctx.moveTo(sx + (R * r) / (1 + r) + R / (1 + r), sy);
        ctx.arc(sx + (R * r) / (1 + r), sy, R / (1 + r), 0, Math.PI * 2);
      }
      ctx.stroke();
      ctx.globalAlpha = 0.35 * intro;
      ctx.beginPath();
      for (const x of [0.2, 0.5, 1, 2, 5]) {
        for (const sgn of [1, -1]) {
          const X = x * sgn;
          for (let i = 0; i <= 90; i++) {
            const r = i === 90 ? 1e5 : Math.tan((i / 90) * (Math.PI / 2));
            const d = (r + 1) ** 2 + X * X;
            const p = map([(r * r + X * X - 1) / d, (2 * X) / d]);
            i ? ctx.lineTo(...p) : ctx.moveTo(...p);
          }
        }
      }
      ctx.stroke();
      ctx.restore();

      // --- locus + sweeping head ---
      const u = still && !motionAllowed() ? 0.45 : (t * 0.07) % 1;
      const head = Math.round(u * STEPS);
      const pts = locus.map(map);
      glowLine(
        pts.slice(0, Math.max(2, Math.round(STEPS * intro))),
        c.accent,
        1.2,
        6,
        0.4,
      );
      ctx.globalCompositeOperation = "lighter";
      const tail = 70;
      for (let i = Math.max(1, head - tail); i <= head; i++) {
        const a = 1 - (head - i) / tail;
        glowLine([pts[i - 1], pts[i]], c.accent, 1 + 2.5 * a, 14 * a, a);
      }
      const hp = pts[head];
      ctx.fillStyle = "#fff";
      ctx.shadowColor = c.accent;
      ctx.shadowBlur = 20;
      ctx.beginPath();
      ctx.arc(...hp, 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.globalCompositeOperation = "source-over";
      // matched centre marker
      ctx.strokeStyle = c.text;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(sx, sy, 3, 0, Math.PI * 2);
      ctx.stroke();

      // --- |S11| plot ---
      const px = stacked ? 18 : sx + R + 40,
        py = stacked ? sy + R + 26 : sy - R * 0.8,
        pw = stacked ? w - 36 : w - px - 14,
        ph = stacked ? h - py - 24 : R * 1.6;
      if (pw > 60 && ph > 50) {
        const yOf = (db) => py + (-db / 40) * ph;
        const xOf = (i) => px + (i / STEPS) * pw;
        ctx.strokeStyle = c.line;
        ctx.lineWidth = 1;
        ctx.strokeRect(px, py, pw, ph);
        ctx.beginPath();
        for (let k = 1; k < 4; k++) {
          ctx.moveTo(px, py + (k * ph) / 4);
          ctx.lineTo(px + pw, py + (k * ph) / 4);
        }
        for (let k = 1; k < 8; k++) {
          ctx.moveTo(px + (k * pw) / 8, py);
          ctx.lineTo(px + (k * pw) / 8, py + ph);
        }
        ctx.stroke();
        // −10 dB reference
        ctx.save();
        ctx.setLineDash([4, 4]);
        ctx.strokeStyle = c.accent;
        ctx.globalAlpha = 0.7;
        ctx.beginPath();
        ctx.moveTo(px, yOf(-10));
        ctx.lineTo(px + pw, yOf(-10));
        ctx.stroke();
        ctx.restore();
        const curve = Array.from({ length: STEPS + 1 }, (_, i) => [
          xOf(i),
          yOf(dbAt(i)),
        ]);
        glowLine(
          curve.slice(0, Math.max(2, Math.round(STEPS * intro))),
          c.phosphor,
          1.8,
          10,
        );
        // sweeping marker
        ctx.save();
        ctx.strokeStyle = c.cyan;
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        ctx.moveTo(xOf(head), py);
        ctx.lineTo(xOf(head), py + ph);
        ctx.stroke();
        ctx.restore();
        ctx.fillStyle = c.cyan;
        ctx.shadowColor = c.cyan;
        ctx.shadowBlur = 12;
        ctx.beginPath();
        ctx.arc(xOf(head), yOf(dbAt(head)), 3.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;
        ctx.font = '9px "JetBrains Mono", monospace';
        ctx.fillStyle = c.muted;
        ctx.fillText(profile.diagrams.lab.plotTop, px + 4, py + 11);
        ctx.fillText(profile.diagrams.lab.plotBottom, px + 4, py + ph - 4);
        ctx.fillText(profile.diagrams.lab.plotStart, px, py + ph + 13);
        ctx.fillText(profile.diagrams.lab.plotEnd, px + pw - 30, py + ph + 13);
        ctx.fillStyle = c.phosphor;
        ctx.fillText(
          profile.diagrams.lab.reflectionAxis,
          px + pw - 56,
          py + 12,
        );
        ctx.fillStyle = c.accent;
        ctx.fillText(profile.diagrams.lab.reference, px + 4, yOf(-10) - 4);
      }
      ctx.font = '9px "JetBrains Mono", monospace';
      ctx.fillStyle = c.phosphor;
      ctx.fillText(
        `${profile.diagrams.lab.marker}  ${(4 + 4 * u).toFixed(2)} ${profile.diagrams.lab.frequencyUnit}`,
        12,
        16,
      );
      if (freq) freq.textContent = (4 + 4 * u).toFixed(2);
      if (s11) s11.textContent = dbAt(head).toFixed(1);
    },
    options,
  );
  return instance;
}

export function destroy() {
  instance?.destroy();
  instance = null;
}
